$liteState = Join-Path $env:ProgramData 'LiteOS'
if (-not (Test-Path -LiteralPath $liteState)) { New-Item -ItemType Directory -Path $liteState -Force | Out-Null }
function Invoke-LiteNative {
    param([string]$FilePath, [string[]]$ArgumentList)
    # local scope only: native stderr must not become a terminating error under 'Stop'
    $ErrorActionPreference = 'Continue'
    $lines = @(& $FilePath @ArgumentList 2>&1 | ForEach-Object { [string]$_ })
    New-Object PSObject -Property @{ ExitCode = $LASTEXITCODE; Output = ($lines -join "`n") }
}

function Get-LiteActiveScheme {
    $r = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @('/getactivescheme')
    $m = [regex]::Match($r.Output, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')
    if (-not $m.Success) { throw ('powercfg /getactivescheme failed: ' + $r.Output) }
    $m.Value.ToLowerInvariant()
}
function Get-LiteSchemes {
    $r = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @('/list')
    $found = @()
    foreach ($m in [regex]::Matches($r.Output, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')) { $found += $m.Value.ToLowerInvariant() }
    $found
}
function Get-LitePowerAc {
    param([string]$Scheme, [string]$SubGroup, [string]$Setting, [switch]$Hidden)
    $verb = '/query'
    if ($Hidden) { $verb = '/qh' }
    $r = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @($verb, $Scheme, $SubGroup, $Setting)
    # locale-independent: the last two 0x values are the AC and DC index
    $ms = [regex]::Matches($r.Output, '0x([0-9a-fA-F]{8})')
    if ($r.ExitCode -ne 0 -or $ms.Count -lt 2) { throw ('Cannot read power setting ' + $Setting + ' of scheme ' + $Scheme + ': ' + $r.Output) }
    [Convert]::ToInt32($ms[$ms.Count - 2].Groups[1].Value, 16)
}
function Set-LitePowerAc {
    param([string]$Scheme, [string]$SubGroup, [string]$Setting, [int]$Value)
    $r = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @('/setacvalueindex', $Scheme, $SubGroup, $Setting, [string]$Value)
    if ($r.ExitCode -ne 0) { throw ('powercfg /setacvalueindex failed: ' + $r.Output) }
}
function Test-LitePortable {
    # laptop / tablet / convertible, or a battery without a desktop chassis (a UPS on a desktop is fine)
    $cs = Get-CimInstance -ClassName Win32_ComputerSystem
    if ([int]$cs.PCSystemType -eq 2) { return $true }
    $portable = @(8, 9, 10, 11, 14, 30, 31, 32)
    $desktop = @(3, 4, 5, 6, 7, 13, 15, 16, 17, 23, 24, 35, 36)
    $isDesktop = $false
    foreach ($enc in @(Get-CimInstance -ClassName Win32_SystemEnclosure)) {
        foreach ($t in @($enc.ChassisTypes)) {
            if ($portable -contains [int]$t) { return $true }
            if ($desktop -contains [int]$t) { $isDesktop = $true }
        }
    }
    $batteries = @(Get-CimInstance -ClassName Win32_Battery -ErrorAction SilentlyContinue)
    if ($batteries.Count -gt 0 -and -not $isDesktop) { return $true }
    return $false
}
function Test-LiteDualCcdX3D {
    # 7900X3D / 7950X3D / 9900X3D / 9950X3D: V-Cache on one CCD only; AMD's driver parks the other
    # CCD for games, which needs the Balanced plan. X3D2 parts have V-Cache on both CCDs.
    foreach ($cpu in @(Get-CimInstance -ClassName Win32_Processor)) {
        $n = [string]$cpu.Name
        if ($n -match 'X3D' -and $n -notmatch 'X3D2' -and [int]$cpu.NumberOfCores -gt 8) { return $true }
    }
    return $false
}
$ultimateBase = 'e9a42b02-d5df-448d-aa00-03f14749eb61'
$liteUltimate = '77bd5e0d-3aa5-45ed-85ff-832218cb02d6'
$balanced = '381b4222-f694-41f0-9685-ff5bb260df2e'
$stateFile = Join-Path $liteState 'prev-powerplan.txt'
if (Test-LitePortable) {
    Write-Output 'SKIPPED: laptop/tablet detected - Ultimate Performance is meant for desktops and would cost battery life.'
} elseif (Test-LiteDualCcdX3D) {
    Write-Output 'SKIPPED: dual-CCD Ryzen X3D CPU detected - AMD 3D V-Cache game scheduling relies on core parking in the Balanced plan, so the power plan is left unchanged.'
} else {
    $schemes = @(Get-LiteSchemes)
    $active = Get-LiteActiveScheme
    $created = ''
    $target = ''
    $why = ''
    if ($schemes -contains $ultimateBase) {
        $target = $ultimateBase
    } elseif ($schemes -contains $liteUltimate) {
        $target = $liteUltimate
    } else {
        $r = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @('/duplicatescheme', $ultimateBase, $liteUltimate)
        if (@(Get-LiteSchemes) -contains $liteUltimate) {
            $target = $liteUltimate
            $created = $liteUltimate
        } else {
            $why = ([string]$r.Output -replace '\s+', ' ').Trim()
        }
    }
    if ($target -eq '') {
        # e.g. PCs with Modern Standby (S0) cannot create the plan
        Write-Output ('SKIPPED: the Ultimate Performance plan is not available on this PC (common on Modern Standby systems), so the power plan is left unchanged. ' + $why)
    } elseif ($active -eq $target) {
        Write-Output 'UNCHANGED: Ultimate Performance is already the active power plan.'
    } else {
        if (-not (Test-Path -LiteralPath $stateFile)) {
            Set-Content -LiteralPath $stateFile -Value @(('prev=' + $active), ('created=' + $created)) -Encoding ASCII
        }
        $r = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @('/setactive', $target)
        if ((Get-LiteActiveScheme) -ne $target) { throw ('Could not activate the Ultimate Performance plan: ' + $r.Output) }
        Write-Output ('LiteOS: Ultimate Performance plan active; previous plan ' + $active + ' saved for revert.')
    }
}

