        $null = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @('/delete', $created)
    }
    Remove-Item -LiteralPath $stateFile -Force
    Write-Output ('LiteOS: power plan ' + $back + ' re-activated.')
} else {
    Write-Output 'LiteOS: no saved power plan (the tweak was skipped or the plan was already active) - nothing to revert.'
}

