    $ErrorActionPreference = 'Continue'
    $lines = @(& $FilePath @ArgumentList 2>&1 | ForEach-Object { [string]$_ })
    New-Object PSObject -Property @{ ExitCode = $LASTEXITCODE; Output = ($lines -join "`n") }
}

function Get-LiteActiveScheme {
    $r = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @('/getactivescheme')
    $m = [regex]::Match($r.Output, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')
    if (-not $m.Success) { throw ('powercfg /getactivescheme failed: ' + $r.Output) }
    $m.Value.ToLowerInvariant()
}
function Get-LiteSchemes {
    $r = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @('/list')
    $found = @()
    foreach ($m in [regex]::Matches($r.Output, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}')) { $found += $m.Value.ToLowerInvariant() }
    $found
}
function Get-LitePowerAc {
    param([string]$Scheme, [string]$SubGroup, [string]$Setting, [switch]$Hidden)
    $verb = '/query'
    if ($Hidden) { $verb = '/qh' }
    $r = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @($verb, $Scheme, $SubGroup, $Setting)
    # locale-independent: the last two 0x values are the AC and DC index
    $ms = [regex]::Matches($r.Output, '0x([0-9a-fA-F]{8})')
    if ($r.ExitCode -ne 0 -or $ms.Count -lt 2) { throw ('Cannot read power setting ' + $Setting + ' of scheme ' + $Scheme + ': ' + $r.Output) }
    [Convert]::ToInt32($ms[$ms.Count - 2].Groups[1].Value, 16)
}
function Set-LitePowerAc {
    param([string]$Scheme, [string]$SubGroup, [string]$Setting, [int]$Value)
    $r = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @('/setacvalueindex', $Scheme, $SubGroup, $Setting, [string]$Value)
    if ($r.ExitCode -ne 0) { throw ('powercfg /setacvalueindex failed: ' + $r.Output) }
}
function Test-LiteDualCcdX3D {
    # 7900X3D / 7950X3D / 9900X3D / 9950X3D: V-Cache on one CCD only; AMD's driver parks the other
    # CCD for games, which needs the Balanced plan. X3D2 parts have V-Cache on both CCDs.
    foreach ($cpu in @(Get-CimInstance -ClassName Win32_Processor)) {
        $n = [string]$cpu.Name
        if ($n -match 'X3D' -and $n -notmatch 'X3D2' -and [int]$cpu.NumberOfCores -gt 8) { return $true }
    }
    return $false
}
$cpuSub = '54533251-82be-4824-96c1-47b60b740d00'
# CPMINCORES and CPMINCORES1 (efficiency class 1 = P-cores on hybrid Intel CPUs)
$cpSettings = @('0cc5b647-c1df-4637-891a-dec35c318583', '0cc5b647-c1df-4637-891a-dec35c318584')
$prefix = 'prev-core-parking-'
if (Test-LiteDualCcdX3D) {
    Write-Output 'SKIPPED: dual-CCD Ryzen X3D CPU detected - AMD 3D V-Cache game scheduling works by parking the non-V-Cache cores.'
} else {
    $scheme = Get-LiteActiveScheme
    $stateFile = Join-Path $liteState ($prefix + $scheme + '.txt')
    $found = @()
    foreach ($s in $cpSettings) {
        $v = $null
        try { $v = Get-LitePowerAc -Scheme $scheme -SubGroup $cpuSub -Setting $s -Hidden } catch { $v = $null }
        if ($null -ne $v) { $found += ($s + '=' + [string]$v) }
    }
    if ($found.Count -eq 0) { throw 'Core parking settings are not available in the active power plan.' }
    $pending = @($found | Where-Object { $_.Substring($_.IndexOf('=') + 1) -ne '100' })
    if ($pending.Count -eq 0) {
        Write-Output ('UNCHANGED: core parking is already off on AC power in plan ' + $scheme + '.')
    } else {
        if (-not (Test-Path -LiteralPath $stateFile)) { Set-Content -LiteralPath $stateFile -Value $found -Encoding ASCII }
        foreach ($line in $found) {
            Set-LitePowerAc -Scheme $scheme -SubGroup $cpuSub -Setting $line.Substring(0, $line.IndexOf('=')) -Value 100
        }
        $null = Invoke-LiteNative -FilePath 'powercfg.exe' -ArgumentList @('/setactive', $scheme)
        Write-Output ('LiteOS: core parking disabled on AC power in plan ' + $scheme + '.')
    }
}

