function Assert-LiteSysMain {
    $svc = Get-Service -Name 'SysMain' -ErrorAction SilentlyContinue
    if ($null -eq $svc) { throw 'The SysMain service is missing; Windows needs it to change memory compression.' }
    if ([string]$svc.StartType -eq 'Disabled') {
        throw 'The SysMain service is disabled; Windows only lets you change memory compression while SysMain is allowed to run. Set SysMain back to Automatic (or revert the Lite OS SysMain tweak) and try again.'
    }
}
Assert-LiteSysMain
$was = [bool](Get-MMAgent).MemoryCompression
if (-not $was) {
    Write-Output 'UNCHANGED: memory compression is already off.'
} else {
    if (-not (Test-Path -LiteralPath $stateFile)) { Set-Content -LiteralPath $stateFile -Value ([string]$was) -Encoding ASCII }
    Disable-MMAgent -MemoryCompression
    Write-Output 'LiteOS: memory compression is off after the next restart.'
}

